formulas.expression:
IF( TEXT( {!v_SglRecPlacement.TransactionType__c} ) = "END"
 , {!v_SglRecPlacement.ENDEffectivedDate__c} + {!fm_PremiumPaymentTermDays}
 , IF( TEXT( {!v_SglRecPlacement.TransactionType__c} ) = "New(Non-recurring)" ||
        TEXT( {!v_SglRecPlacement.TransactionType__c} ) = "New(Recurring)" ||
        TEXT( {!v_SglRecPlacement.TransactionType__c} ) = "Renew"
     , {!fm_InstallDate} + {!fm_PremiumPaymentTermDays}
	 , null)	  
)
